{
  "$schema": "https://biomejs.dev/schemas/2.6.8/schema.json",
  "files": {
    "includes": ["ts/**/*.ts", "evals/suites/**/*.ts", "evals/suites/**/*.mjs", "package.json", "biome.json", "tsconfig.json"]
  },
  "formatter": {
    "enabled": false
  },
  "linter": {
    "enabled": true,
    "rules": {
      "preset": "recommended"
    }
  },
  "assist": {
    "actions": {
      "source": {
        "organizeImports": "on"
      }
    }
  }
}

import { agencies } from "../../../ts/src/domains/supply-chain/agencies";
import { deriveSituationSignature } from "../../../ts/src/domains/supply-chain/memory";
import { agencyIds } from "../../../ts/src/domains/supply-chain/types";
import { recallKLines, situationSimilarity } from "../../../ts/src/memory/kline";
import { reinstatementEffects } from "../../../ts/src/memory/reinstatement";
import { similarity } from "../../../ts/src/memory/similarity";
import { activation } from "../../../ts/src/primitives/activation";
import type { AgencyId, ConceptId } from "../../../ts/src/primitives/types";
import { runCycle } from "../../../ts/src/society/cycle";
import { dispatchIsonome } from "../../../ts/src/society/dispatch";
import { type ActivateAgency, applyEffect } from "../../../ts/src/workspace/effect";
import { createEmptyWorkspace } from "../../../ts/src/workspace/workspace";
import type { Condition, MemoryBank, Observation, SelectionKind } from "./types";

// Broad, semantic routing table, fixed before scored runs. Signal presence rather
// than Society thresholds determines selection; labels are never arguments.
export const routingTable: Readonly<Record<ConceptId, readonly AgencyId[]>> = {
  SHIPMENT_DELAY: ["LOGISTICS_ASSESSMENT", "INVENTORY_ASSESSMENT"],
  INVENTORY_RISK: ["INVENTORY_ASSESSMENT", "PRODUCTION_ASSESSMENT"],
  SUPPLIER_RELIABILITY_RISK: ["SUPPLIER_ASSESSMENT", "PROCUREMENT_STRATEGY", "RISK_ASSESSMENT"],
  PRODUCTION_IMPACT: ["PRODUCTION_ASSESSMENT", "RISK_ASSESSMENT", "CUSTOMER_COMMITMENT"],
  ALTERNATIVE_SUPPLIER_AVAILABLE: ["PROCUREMENT_STRATEGY", "COMPLIANCE_ASSESSMENT"],
  COMPLIANCE_UNVERIFIED: ["COMPLIANCE_ASSESSMENT"],
  HIGH_PRIORITY_ORDER: ["CUSTOMER_COMMITMENT", "PRODUCTION_ASSESSMENT"],
  REPEAT_DISRUPTION: ["SUPPLIER_ASSESSMENT", "PROCUREMENT_STRATEGY", "RISK_ASSESSMENT"],
  ROUTE_DISRUPTION: ["LOGISTICS_ASSESSMENT"],
  QUALITY_RISK: ["COMPLIANCE_ASSESSMENT", "SUPPLIER_ASSESSMENT", "RISK_ASSESSMENT"],
  CUSTOMER_COMMITMENT_RISK: ["CUSTOMER_COMMITMENT", "RISK_ASSESSMENT"],
};

export function createWorkspace(observation: Observation) {
  let workspace = createEmptyWorkspace();
  for (const [key, value] of Object.entries(observation.facts)) workspace = applyEffect(workspace, { action: "record_fact", key, value });
  for (const binding of observation.bindings) workspace = applyEffect(workspace, { action: "bind_pronome", roleId: binding.roleId, value: binding.value });
  for (const concept of observation.concepts) workspace = applyEffect(workspace, { action: "emit_polyneme", conceptId: concept.id, strength: activation(concept.strength) });
  for (const operationId of ["VERIFY", "COMPARE"] as const) workspace = applyEffect(workspace, { action: "invoke_isonome", operationId, strength: activation(1) });
  return workspace;
}

export function directRoute(observation: Observation): readonly AgencyId[] {
  const selected = new Set(observation.concepts.filter(concept => concept.strength > 0).flatMap(concept => routingTable[concept.id]));
  return agencyIds.filter(id => selected.has(id));
}

export function selectOrganization(condition: Condition, observation: Observation, memories: MemoryBank) {
  const workspace = createWorkspace(observation);
  let selectedMemoryId: string | null = null;
  let selectedSimilarity: number | null = null;
  let contributions: readonly ActivateAgency[] = [];
  let selectionKind: SelectionKind = "threshold-recruitment";
  let selected: readonly AgencyId[];
  const recruited: readonly AgencyId[] = [];
  let currentWorkspace = workspace;
  const trace: ReturnType<typeof runCycle>["trace"] = [];
  if (condition === "organization-memory") {
    const match = recallKLines(deriveSituationSignature(workspace), memories.klines, similarity(0))[0];
    if (match) {
      selectedMemoryId = match.kline.id;
      selectedSimilarity = match.similarity;
      contributions = reinstatementEffects(match);
      currentWorkspace = contributions.reduce(applyEffect, workspace);
    }
  }
  if (condition === "no-memory" || condition === "organization-memory") {
    const cycle = runCycle(currentWorkspace, agencies);
    return { workspace: cycle.workspace, dispatches: cycle.dispatches, trace: cycle.trace,
      selected: cycle.recruitedAgencyIds, recruited: cycle.recruitedAgencyIds,
      selectedMemoryId, selectedSimilarity, contributions, selectionKind };
  }
  if (condition === "direct-routing") {
    selectionKind = "direct-routing";
    selected = directRoute(observation);
  } else {
    const signature = deriveSituationSignature(workspace);
    const matches = memories.episodes.map(episode => ({ episode, score: situationSimilarity(signature, episode.signature) }))
      .filter(match => match.score > 0).sort((a, b) => b.score - a.score || (a.episode.id < b.episode.id ? -1 : a.episode.id > b.episode.id ? 1 : 0));
    const match = matches[0];
    selectionKind = match ? "episode-replay" : "direct-routing";
    selected = match ? match.episode.advice.agencyIds : directRoute(observation);
    selectedMemoryId = match?.episode.id ?? null;
    selectedSimilarity = match?.score ?? null;
  }
  const dispatches = workspace.isonomes.flatMap(isonome => dispatchIsonome(isonome, selected, agencies));
  return { workspace, dispatches, trace, selected, recruited, selectedMemoryId, selectedSimilarity, contributions, selectionKind };
}

import { agencies } from "../../../ts/src/domains/supply-chain/agencies";
import type { AgencyId } from "../../../ts/src/primitives/types";
import type { AgencyOperationDispatch } from "../../../ts/src/society/dispatch";
import { type AgencyRuntime, executeDispatch } from "../../../ts/src/society/execution";
import type { WorkspaceState } from "../../../ts/src/workspace/workspace";
import { type Assessment, assessmentBudget, type FindingId, findingIds, type SituationFacts } from "./types";

// Conditional mock observations. No case IDs, concepts, requirements, or scores.
export function findingsFor(id: AgencyId, facts: SituationFacts): readonly FindingId[] {
  const shortage = facts.stockDays < facts.demandDays;
  const alternate = facts.alternateSupplier && facts.complianceRecord;
  const recoverable = facts.reserveStock || facts.alternativeRoute || alternate;
  switch (id) {
    case "SUPPLIER_ASSESSMENT": return [
      ...(facts.supplierUnreliable ? ["supplier-risk" as const] : []),
      ...(alternate ? ["alternate-source" as const] : []),
      ...(facts.qualityAlert ? ["quality-hold" as const] : []),
    ];
    case "INVENTORY_ASSESSMENT": return [
      ...(shortage ? ["inventory-impact" as const] : []),
      ...(shortage && facts.productionAtRisk ? ["production-impact" as const] : []),
      ...(facts.reserveStock ? ["buffer-option" as const] : []),
    ];
    case "LOGISTICS_ASSESSMENT": return [
      ...(facts.routeBlocked ? ["route-risk" as const] : []),
      ...(facts.alternativeRoute ? ["reroute-option" as const] : []),
      ...(facts.routeBlocked && facts.customerAtRisk ? ["customer-impact" as const] : []),
    ];
    case "PRODUCTION_ASSESSMENT": return [
      ...(facts.productionAtRisk ? ["production-impact" as const] : []),
      ...(recoverable ? ["recovery-option" as const] : []),
    ];
    case "PROCUREMENT_STRATEGY": return [
      ...(alternate ? ["alternate-source" as const] : []),
      ...(facts.alternateSupplier && !facts.complianceRecord ? ["supplier-verification-needed" as const] : []),
      ...(facts.reserveStock ? ["buffer-option" as const] : []),
    ];
    case "COMPLIANCE_ASSESSMENT": return [
      ...(facts.complianceRecord ? ["compliance-verified" as const] : []),
      ...(facts.qualityAlert ? ["quality-hold" as const] : []),
      ...(facts.alternateSupplier && !facts.complianceRecord ? ["supplier-verification-needed" as const] : []),
    ];
    case "RISK_ASSESSMENT": return [
      ...(facts.supplierUnreliable ? ["supplier-risk" as const] : []),
      ...(facts.productionAtRisk ? ["production-impact" as const] : []),
      ...(facts.customerAtRisk ? ["customer-impact" as const] : []),
      ...(facts.qualityAlert ? ["quality-hold" as const] : []),
    ];
    case "CUSTOMER_COMMITMENT": return [
      ...(facts.customerAtRisk ? ["customer-impact" as const] : []),
      ...(facts.productionAtRisk && recoverable ? ["recovery-option" as const] : []),
    ];
  }
}

export function assessmentOperation(id: AgencyId) {
  const agency = agencies.find(agency => agency.id === id);
  if (!agency) throw new Error(`Missing agency configuration: ${id}`);
  return agency.supportedOperations.includes("VERIFY") ? "VERIFY" as const : "COMPARE" as const;
}

export const runtimes: readonly AgencyRuntime[] = agencies.map(agency => ({
  agencyId: agency.id,
  operations: { [assessmentOperation(agency.id)]: ({ workspace }: { workspace: WorkspaceState }): Assessment => ({
    findings: findingsFor(agency.id, workspace.facts as SituationFacts),
  }) },
}));

/** One assessment per agency, canonical agency order, same budget for all arms. */
export async function executeAssessments(workspace: WorkspaceState, dispatches: readonly AgencyOperationDispatch[]) {
  const candidates = agencies.flatMap(agency => {
    const request = dispatches.find(dispatch => dispatch.agencyId === agency.id && dispatch.operationId === assessmentOperation(agency.id));
    return request ? [request] : [];
  });
  const selected = candidates.slice(0, assessmentBudget);
  const executions = [];
  for (const dispatch of selected) {
    const result = await executeDispatch(dispatch, workspace, agencies, runtimes);
    const value = result.value as Assessment;
    if (!value || !Array.isArray(value.findings) || value.findings.some(finding => !findingIds.includes(finding))) {
      throw new Error(`Invalid assessment output: ${dispatch.agencyId}`);
    }
    executions.push({ ...result, value });
  }
  return { executions, skippedForBudget: candidates.slice(assessmentBudget), assessmentCandidates: candidates };
}

import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { appendFileSync, existsSync, mkdirSync, mkdtempSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { cpus, release, tmpdir, totalmem } from "node:os";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "../../..");
const suitePath = "evals/suites/organization-memory";
const protocolPath = "evals/protocols/organization-memory.md";
const registrationPath = join(root, suitePath, "registration.json");
const resultRoot = join(root, "evals/results/organization-memory");
const encode = value => `${JSON.stringify(value, null, 2)}\n`;
const hash = text => createHash("sha256").update(text).digest("hex");
const readJSON = path => JSON.parse(readFileSync(path, "utf8"));
const writeJSON = (path, value) => writeFileSync(path, encode(value), { flag: "wx" });
const git = args => execFileSync("git", args, { cwd: root, encoding: "utf8" }).trim();
function filesIn(path) {
  return readdirSync(path, { withFileTypes: true }).flatMap(entry => entry.isDirectory()
    ? filesIn(join(path, entry.name)) : [join(path, entry.name)]);
}
function sourceSnapshot() {
  const paths = [...filesIn(join(root, "ts")), ...filesIn(join(root, suitePath))]
    .filter(path => /\.(ts|mjs)$/.test(path) || path.endsWith("/README.md"));
  paths.push(...["package.json", "pnpm-lock.yaml", "tsconfig.json", "biome.json", protocolPath].map(path => join(root, path)));
  return { version: 1, files: paths.sort().map(path => ({ path: relative(root, path), content: readFileSync(path, "utf8") })) };
}
function refreshIndex() {
  const rows = existsSync(resultRoot) ? readdirSync(resultRoot).sort().flatMap(id => {
    const directory = join(resultRoot, id);
    if (!existsSync(join(directory, "manifest.json"))) return [];
    const manifest = readJSON(join(directory, "manifest.json"));
    const summary = existsSync(join(directory, "summary.json")) ? readJSON(join(directory, "summary.json")) : null;
    return [`| [${id}](organization-memory/${id}/report.md) | H7 / protocol v1 | ${manifest.status} | ${manifest.status === "completed" ? summary?.evidenceStatus ?? "no evidence" : "no valid evidence"} | ${manifest.replicationOf ? "Determinism replication" : "Initial comparison"} |`];
  }) : [];
  const path = join(root, "evals/results/README.md");
  let text = readFileSync(path, "utf8");
  const table = `<!-- organization-memory-runs:start -->\n| Run | Scope | Status | Evidence | Purpose |\n| --- | --- | --- | --- | --- |\n${rows.join("\n")}\n<!-- organization-memory-runs:end -->`;
  const pattern = /<!-- organization-memory-runs:start -->[\s\S]*?<!-- organization-memory-runs:end -->/;
  text = pattern.test(text) ? text.replace(pattern, table) : `${text.trim()}\n\n## Recorded organization-memory runs\n\n${table}\n`;
  // Update only the index's state sentences, preserving other workstreams/history.
  text = text.replace("No completed comparative evaluations are currently recorded. No comparative performance advantage over another architecture is currently claimed.",
    "Organization-memory H7 comparative runs are recorded below. Evidence is scoped to the deterministic mock-domain protocol; no general performance advantage is claimed.");
  text = text.replace("No runs; [initial protocol](../protocols/organization-memory.md) is a design draft.",
    "See the preserved H7 runs below and [protocol v1](../protocols/organization-memory.md).");
  writeFileSync(path, text);
}

function report(manifest, result) {
  const { summary, measurements, training } = result;
  const fmt = number => number.toFixed(4);
  const table = stats => ["| Condition | Mean coverage | Median | Min–max | Mean executions | Mean selected | Mean recruits | Mean dispatches | Mean unnecessary | Perfect | Zero |",
    "| --- | ---: | ---: | --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: |",
    ...Object.entries(stats).map(([condition, value]) => `| ${condition} | ${fmt(value.meanCoverage)} | ${fmt(value.medianCoverage)} | ${fmt(value.minCoverage)}–${fmt(value.maxCoverage)} | ${fmt(value.meanAgencyExecutions)} | ${fmt(value.meanSelectedAgencies)} | ${fmt(value.meanRecruitedAgencies)} | ${fmt(value.meanDispatchCount)} | ${fmt(value.meanUnnecessaryExecutions)} | ${value.perfectCoverageCases} | ${value.zeroCoverageCases} |`)].join("\n");
  const blocks = [
    `# H7 organization-memory comparison: ${manifest.runId}`,
    `## Run metadata\n\nRun ID: ${manifest.runId}. Time: ${manifest.startedAt}. Hypothesis: H7. Protocol: [organization-memory v1](../../../protocols/organization-memory.md), SHA-256 ${manifest.protocol.sha256}. Suite: ${manifest.suite.version}. Base commit: ${manifest.source.commit}. Dirty working tree: ${manifest.source.dirty}. Source snapshot: [source-snapshot.json](source-snapshot.json), SHA-256 ${manifest.source.snapshotSha256}. ${manifest.replicationOf ? `Determinism replication of ${manifest.replicationOf}.` : "First scored execution under the registered protocol."}`,
    "## Research question\n\nWhen a new situation is structurally related to a previous episode but has different literal referents, does organization-memory reinstatement improve task outcome or computational efficiency relative to reasonable alternatives?",
    "## Conditions\n\nNo memory uses the unchanged Society cycle. Organization memory adds one top recalled match's production H6 activation Effects before propagation. Direct routing unions the fixed semantic concept-to-capability table for positive signals. Episode retrieval replays the nearest stored episode's routing recommendation, falling back to direct routing when no positive match exists. All conditions receive the same observations, capabilities, four-assessment budget, common execution scheduler, and scorer. See the [frozen suite specification](../../../suites/organization-memory/README.md) and recoverable source snapshot for exact policies.",
    `## Dataset\n\nMemory formation: ${manifest.dataset.formationCases} cases. Held-out: ${manifest.dataset.scoredCases} distinct cases, eight each related, partial, unrelated, misleading. All five role occupants differ between formation and held-out episodes. No held-out outcomes were used for memory formation, routing rules, parameter tuning, or registration. [inputs.json](inputs.json) preserves facts, concepts, requirements, configuration, and routing table.`,
    "## Primary metric\n\nTask coverage = unique required findings produced by executed assessments / unique required findings. It is not coalition agreement. Conditional handlers derive findings from current facts; several different capabilities can satisfy overlapping requirements. Every case has at least one requirement.",
    "## Secondary metrics\n\nLocal handler executions, selected agencies, actual threshold recruits, all dispatch requests, unnecessary executions (a handler produces no required finding), skipped assessments, recall comparisons, and reinstatement Effects. Direct/replay policies bypass recruitment, so their actual threshold-recruit count is zero; selected count is provided for comparing organization size. All counts are deterministic work proxies. No measured latency, energy, amortized gain, significance test, or population generalization is claimed.",
    `## Results\n\nGenerated observations, all ${manifest.dataset.scoredCases * 4} paired observations completed.\n\n${table(summary.byCondition)}`,
    ...Object.entries(summary.byClass).map(([kind, stats]) => `### ${kind}\n\n${table(stats)}`),
    `## Pairwise comparison\n\nDifferences are organization memory minus the named baseline. Coverage is in [0,1] units; positive execution difference means more work.\n\n| Baseline | Mean coverage difference | Mean execution difference |\n| --- | ---: | ---: |\n${summary.pairs.map(pair => `| ${pair.baseline} | ${fmt(pair.meanCoverageDifference)} | ${fmt(pair.meanExecutionDifference)} |`).join("\n")}`,
    `### Class-level coverage differences\n\n| Baseline | Related | Partial | Unrelated | Misleading |\n| --- | ---: | ---: | ---: | ---: |\n${summary.pairs.map(pair => `| ${pair.baseline} | ${["related", "partial", "unrelated", "misleading"].map(kind => fmt(pair.byClass[kind])).join(" | ")} |`).join("\n")}`,
    `## Formation and memory overhead\n\n${training.measurements.length} formation cycles; ${training.measurements.reduce((sum, row) => sum + row.executions, 0)} formation handler executions; ${training.measurements.reduce((sum, row) => sum + row.dispatches, 0)} formation dispatch requests. Each memory condition is charged that cold-start execution work separately. Organization memory stores ${training.bank.klines.length} K-lines with ${training.measurements.reduce((sum, row) => sum + row.storedActivationEntries, 0)} activation entries; episode retrieval stores ${training.bank.episodes.length} episode/advice records. Each memory arm scans eight signatures per held-out case (256 total). Organization memory generated/applied ${measurements.filter(row => row.condition === "organization-memory").reduce((sum, row) => sum + row.costs.reinstatementEffectCount, 0)} activation Effects. These dimensions are not added into an arbitrary total-cost score.`,
    `## Observed failure cases\n\nThe following organization-memory cases have incomplete task coverage; no case was removed or repaired after scoring. Missing findings and skipped assessments are retained in raw results.\n\n| Case | Class | Coverage | Missing findings | Skipped assessments | Unnecessary executions |\n| --- | --- | ---: | --- | ---: | ---: |\n${measurements.filter(row => row.condition === "organization-memory" && row.coverage < 1).map(row => `| ${row.caseId} | ${row.caseClass} | ${fmt(row.coverage)} | ${row.missing.join(", ")} | ${row.costs.skippedAssessments} | ${row.unnecessaryExecutions} |`).join("\n")}`,
    `## Interpretation\n\n${summary.interpretation}\n\nThis is the predeclared descriptive classification, not a claim of broad scientific support. The full class and baseline comparisons govern the scope; increased coverage alone establishes no efficiency advantage. Misleading cases expose boundaries relevant to H8/H11 but do not complete those investigations.`,
    "## Limitations\n\nDeterministic mock domain; small sample; hand-authored task requirements, facts, concepts, and semantic routing table; simple Jaccard similarity; fixed canonical agency priority and four-assessment budget; no stochastic capabilities; no real LLM/tool/API calls; no claim of cognitive validity, realistic business performance, general agent benefit, biological plausibility, cross-domain superiority, sophisticated-planner advantage, or production usefulness. Memory-only and no-memory use graded activation while the direct baseline uses signal presence. Baseline schedules and handlers are matched, but selection mechanisms differ by design. Findings have only informational value; negative effects are omissions and budget displacement, not harmful business actions. No utility selection, aggregation, forgetting, or H6 modification was made.",
    `## H7 status\n\nInvestigated — ${summary.evidenceStatus} under this run. H6 remains operationalized and unchanged. H8–H11 remain separate questions. [Manifest](manifest.json), [case results](cases.json), [raw measurements](measurements.jsonl), [summary](summary.json), and [formation artifacts](memories.json) preserve this attempt.`,
  ];
  return `${blocks.join("\n\n")}\n`;
}

const args = process.argv.slice(2);
if (args.some((arg, i) => arg !== "--register" && arg !== "--replicate-of" && args[i - 1] !== "--replicate-of")) {
  throw new Error("Usage: npm run eval:organization-memory -- [--register | --replicate-of RUN_ID]");
}
const build = mkdtempSync(join(tmpdir(), "society-h7-"));
try {
  execFileSync(join(root, "node_modules/.bin/tsc"), ["--project", "tsconfig.json", "--noEmit", "false", "--outDir", build], { cwd: root, stdio: "inherit" });
  const require = createRequire(import.meta.url);
  const compiled = path => require(join(build, suitePath, path));
  const { formationCases, heldOutCases } = compiled("cases.js");
  const { runExperiment } = compiled("run.js");
  const { conditions, suiteVersion, assessmentBudget } = compiled("types.js");
  const { routingTable } = compiled("baselines.js");
  const { agencies } = require(join(build, "ts/src/domains/supply-chain/agencies.js"));
  const inputs = { formationCases, heldOutCases, agencies, routingTable, assessmentBudget };
  const trainingIds = new Set(formationCases.map(task => task.id));
  const trainingReferents = new Set(formationCases.flatMap(task => task.observation.bindings.map(binding => binding.value)));
  if (heldOutCases.some(task => trainingIds.has(task.id) || task.observation.bindings.some(binding => trainingReferents.has(binding.value)))) {
    throw new Error("Memory formation/held-out leakage");
  }
  const snapshot = sourceSnapshot();
  const snapshotHash = hash(encode(snapshot));
  const inputHash = hash(encode(inputs));
  if (args.includes("--register")) {
    writeJSON(registrationPath, { protocolVersion: "v1", suiteVersion, registeredAt: new Date().toISOString(),
      sourceSnapshotSha256: snapshotHash, inputSha256: inputHash,
      files: snapshot.files.map(file => ({ path: file.path, sha256: hash(file.content) })),
      note: "Frozen before held-out execution. Development tests use formation-derived cases only." });
    process.stdout.write(`Registered protocol v1 before scoring. Source SHA-256: ${snapshotHash}\n`);
  } else {
    const registration = readJSON(registrationPath);
    if (registration.sourceSnapshotSha256 !== snapshotHash || registration.inputSha256 !== inputHash) {
      throw new Error("Frozen source/input mismatch; do not score a changed registered experiment");
    }
    const replicationOf = args.includes("--replicate-of") ? args[args.indexOf("--replicate-of") + 1] : null;
    if (args.includes("--replicate-of") && (!replicationOf || !/^[a-zA-Z0-9_-]+$/.test(replicationOf))) throw new Error("Invalid replication run ID");
    const runId = `${new Date().toISOString().replace(/[-:.]/g, "")}-h7`;
    mkdirSync(resultRoot, { recursive: true });
    const directory = join(resultRoot, runId);
    mkdirSync(directory);
    const packageInfo = readJSON(join(root, "package.json"));
    const status = git(["status", "--porcelain=v1", "--untracked-files=all"]);
    const manifest = { runId, startedAt: new Date().toISOString(), status: "running", hypothesisIds: ["H7"],
      contextHypotheses: ["H6", "H8", "H20"], workstream: "organizational-memory/control", domain: "deterministic-supply-chain",
      protocol: { path: protocolPath, version: "v1", sha256: hash(readFileSync(join(root, protocolPath))) },
      suite: { path: suitePath, version: suiteVersion }, registration,
      source: { commit: git(["rev-parse", "HEAD"]), dirty: status.length > 0, status, snapshot: "source-snapshot.json", snapshotSha256: snapshotHash },
      inputs: { path: "inputs.json", sha256: inputHash },
      dataset: { formationCases: formationCases.length, scoredCases: heldOutCases.length,
        classes: Object.fromEntries(["related", "partial", "unrelated", "misleading"].map(kind => [kind, heldOutCases.filter(task => task.class === kind).length])) },
      conditions, primaryOutcome: "unique required findings produced / unique required findings",
      secondaryMetrics: ["executions", "selected agencies", "threshold recruits", "dispatches", "unnecessary executions", "recall comparisons", "reinstatement effects", "skipped assessments"],
      rules: { reinstatement: "stored activation * Jaccard similarity", similarity: "concept-set Jaccard; empty/zero matches excluded", selection: "top positive match; ID ascending ties", utility: "not used", aggregation: "none" },
      budgets: { localAssessmentsPerCase: assessmentBudget, repeatedCycles: false, seeds: [], repetitions: 1, heldOutTuning: 0 },
      invocation: { argv: process.argv, npmCommand: process.env.npm_lifecycle_script ?? null, cwd: root }, replicationOf,
      environment: { node: process.version, versions: process.versions, platform: process.platform, arch: process.arch,
        hardware: { cpuModel: cpus()[0]?.model ?? "unknown", logicalCPUs: cpus().length, memoryBytes: totalmem(), osRelease: release() },
        dependencies: packageInfo.dependencies, devDependencies: packageInfo.devDependencies, externalModels: [], externalAPIs: [] },
      notes: ["Dirty source is recoverable from source-snapshot.json. Private research and Codex files are excluded.", "All measurements are deterministic counts/coverage, not hardware timing."] };
    writeJSON(join(directory, "manifest.json"), manifest);
    writeJSON(join(directory, "source-snapshot.json"), snapshot);
    writeJSON(join(directory, "inputs.json"), inputs);
    try {
      const result = await runExperiment(heldOutCases, formationCases, row => appendFileSync(join(directory, "measurements.jsonl"), `${JSON.stringify(row)}\n`));
      writeJSON(join(directory, "cases.json"), result.measurements);
      writeJSON(join(directory, "memories.json"), result.training);
      writeJSON(join(directory, "summary.json"), result.summary);
      if (replicationOf) {
        const previous = join(resultRoot, replicationOf);
        const verification = {
          identicalCases: encode(result.measurements) === encode(readJSON(join(previous, "cases.json"))),
          identicalSummary: encode(result.summary) === encode(readJSON(join(previous, "summary.json"))),
          identicalMemories: encode(result.training) === encode(readJSON(join(previous, "memories.json"))),
        };
        writeJSON(join(directory, "replication.json"), verification);
        if (Object.values(verification).some(value => !value)) throw new Error("Deterministic replication mismatch");
      }
      manifest.status = "completed";
      manifest.finishedAt = new Date().toISOString();
      writeFileSync(join(directory, "manifest.json"), encode(manifest));
      writeFileSync(join(directory, "report.md"), report(manifest, result), { flag: "wx" });
      process.stdout.write(`Organization Memory Evaluation\nRun: ${runId}\nCases: ${heldOutCases.length}\n\nCondition              Coverage   Executions\n`);
      for (const condition of conditions) {
        const value = result.summary.byCondition[condition];
        process.stdout.write(`${condition.padEnd(23)}${value.meanCoverage.toFixed(4).padEnd(11)}${value.meanAgencyExecutions.toFixed(4)}\n`);
      }
      process.stdout.write(`\n${result.summary.interpretation}\n\nArtifacts: evals/results/organization-memory/${runId}/report.md\n`);
    } catch (error) {
      manifest.status = "invalid";
      manifest.finishedAt = new Date().toISOString();
      writeFileSync(join(directory, "manifest.json"), encode(manifest));
      writeJSON(join(directory, "failure.json"), { message: String(error), stack: error instanceof Error ? error.stack : null });
      if (!existsSync(join(directory, "cases.json"))) {
        const rows = existsSync(join(directory, "measurements.jsonl")) ? readFileSync(join(directory, "measurements.jsonl"), "utf8").trim().split("\n").filter(Boolean).map(line => JSON.parse(line)) : [];
        writeJSON(join(directory, "cases.json"), rows);
      }
      writeFileSync(join(directory, "report.md"), `# Invalid H7 attempt: ${runId}\n\n${String(error)}\n\nNo H7 evidence is inferred. Preserve [manifest](manifest.json), [failure](failure.json), and partial observations; repair requires a new run.\n`);
      throw error;
    } finally { refreshIndex(); }
  }
} finally { rmSync(build, { recursive: true, force: true }); }

import { selectOrganization } from "./baselines";
import { executeAssessments } from "./capabilities";
import { scoreTask } from "./scorer";
import { formMemories } from "./training";
import { type Condition, classes, conditions, type MemoryBank, type TaskCase } from "./types";

export async function evaluateCase(task: TaskCase, condition: Condition, memories: MemoryBank) {
  // The policy gets only observation. Required findings are introduced after execution.
  const selection = selectOrganization(condition, task.observation, memories);
  const work = await executeAssessments(selection.workspace, selection.dispatches);
  const score = scoreTask(task.requiredFindings, work.executions.map(result => result.value));
  const usesMemory = condition === "organization-memory" || condition === "episode-retrieval";
  return {
    caseId: task.id, caseClass: task.class, description: task.description, condition, status: "completed" as const,
    observation: task.observation, requirements: task.requiredFindings,
    selectedMemoryId: selection.selectedMemoryId, similarity: selection.selectedSimilarity,
    reinstatementContributions: selection.contributions, selectionKind: selection.selectionKind,
    selectedAgencyIds: selection.selected, recruitedAgencyIds: selection.recruited,
    dispatches: selection.dispatches, assessmentCandidates: work.assessmentCandidates,
    skippedForBudget: work.skippedForBudget, executedAgencies: work.executions.map(result => result.agencyId),
    executionOutputs: work.executions, cycleTrace: selection.trace, ...score,
    costs: {
      executionCount: work.executions.length, recruitedCount: selection.recruited.length,
      selectedCount: selection.selected.length, dispatchCount: selection.dispatches.length,
      unnecessaryExecutions: score.unnecessaryExecutions,
      recallComparisons: usesMemory ? memories.klines.length : 0,
      signatureDerivations: usesMemory ? 1 : 0,
      reinstatementEffectCount: selection.contributions.length,
      skippedAssessments: work.skippedForBudget.length,
    },
  };
}
export type Measurement = Awaited<ReturnType<typeof evaluateCase>>;

function aggregate(rows: readonly Measurement[]) {
  if (!rows.length) throw new Error("Cannot aggregate an empty condition");
  const coverage = rows.map(row => row.coverage).sort((a, b) => a - b);
  const mean = (numbers: readonly number[]) => numbers.reduce((sum, value) => sum + value, 0) / numbers.length;
  const middle = Math.floor(coverage.length / 2);
  return {
    caseCount: rows.length, meanCoverage: mean(coverage),
    medianCoverage: coverage.length % 2 ? coverage[middle] : (coverage[middle - 1] + coverage[middle]) / 2,
    minCoverage: coverage[0], maxCoverage: coverage[coverage.length - 1],
    meanAgencyExecutions: mean(rows.map(row => row.costs.executionCount)),
    meanRecruitedAgencies: mean(rows.map(row => row.costs.recruitedCount)),
    meanSelectedAgencies: mean(rows.map(row => row.costs.selectedCount)),
    meanDispatchCount: mean(rows.map(row => row.costs.dispatchCount)),
    meanUnnecessaryExecutions: mean(rows.map(row => row.costs.unnecessaryExecutions)),
    meanRecallComparisons: mean(rows.map(row => row.costs.recallComparisons)),
    meanReinstatementEffects: mean(rows.map(row => row.costs.reinstatementEffectCount)),
    perfectCoverageCases: coverage.filter(value => value === 1).length,
    zeroCoverageCases: coverage.filter(value => value === 0).length,
  };
}

export function summarize(rows: readonly Measurement[]) {
  const byCondition = Object.fromEntries(conditions.map(condition => [condition,
    aggregate(rows.filter(row => row.condition === condition)),
  ])) as Record<Condition, ReturnType<typeof aggregate>>;
  const byClass = Object.fromEntries(classes.filter(kind => rows.some(row => row.caseClass === kind)).map(kind => [kind,
    Object.fromEntries(conditions.map(condition => [condition, aggregate(rows.filter(row => row.condition === condition && row.caseClass === kind))])),
  ])) as Record<string, Record<Condition, ReturnType<typeof aggregate>>>;
  const organization = byCondition["organization-memory"];
  const pairs = conditions.filter(condition => condition !== "organization-memory").map(baseline => ({
    baseline,
    meanCoverageDifference: organization.meanCoverage - byCondition[baseline].meanCoverage,
    meanExecutionDifference: organization.meanAgencyExecutions - byCondition[baseline].meanAgencyExecutions,
    byClass: Object.fromEntries(Object.entries(byClass).map(([kind, stats]) => [kind,
      stats["organization-memory"].meanCoverage - stats[baseline].meanCoverage])),
    cases: rows.filter(row => row.condition === "organization-memory").map(row => {
      const other = rows.find(candidate => candidate.caseId === row.caseId && candidate.condition === baseline);
      if (!other) throw new Error(`Missing paired observation: ${baseline}.${row.caseId}`);
      return { caseId: row.caseId, coverageDifference: row.coverage - other.coverage,
        executionDifference: row.costs.executionCount - other.costs.executionCount };
    }),
  }));
  const noMemory = byCondition["no-memory"];
  const classLoss = Object.values(byClass).some(stats => stats["organization-memory"].meanCoverage < stats["no-memory"].meanCoverage);
  const betterThanAll = pairs.every(pair => pair.meanCoverageDifference > 0);
  const matchedQualityCheaper = pairs.every(pair => pair.meanCoverageDifference >= 0 && pair.meanExecutionDifference <= 0)
    && pairs.some(pair => pair.meanExecutionDifference < 0);
  let evidenceStatus: string;
  let interpretation: string;
  if (betterThanAll && !classLoss || matchedQualityCheaper && !classLoss) {
    evidenceStatus = "initial-support";
    interpretation = "Initial support under protocol v1: organization memory showed a coverage or matched-quality execution advantage over every declared baseline without a class-level coverage loss to no memory.";
  } else if (organization.meanCoverage > noMemory.meanCoverage) {
    evidenceStatus = "mixed";
    interpretation = "Mixed under protocol v1: organization memory improved mean task coverage over no memory, but did not establish a consistent quality-and-cost advantage over the declared alternatives.";
  } else {
    evidenceStatus = "unsupported";
    interpretation = "Unsupported under protocol v1: organization memory did not improve mean task coverage over no memory or establish a matched-quality execution advantage over the declared alternatives.";
  }
  return { status: "completed", primaryMetric: "task-coverage", byCondition, byClass, pairs, evidenceStatus, interpretation };
}

export async function runExperiment(scoredCases: readonly TaskCase[], trainingCases: readonly TaskCase[], record: (row: Measurement) => void = () => {}) {
  const training = await formMemories(trainingCases);
  const measurements: Measurement[] = [];
  for (const task of scoredCases) {
    for (const condition of conditions) {
      const row = await evaluateCase(task, condition, training.bank);
      measurements.push(row);
      record(row);
    }
  }
  return { measurements, training, summary: summarize(measurements) };
}

import type { Assessment, FindingId } from "./types";

/** Score executed information, with no agency identities or routing knowledge. */
export function scoreTask(required: readonly FindingId[], outputs: readonly Assessment[]) {
  const requirements = [...new Set(required)];
  if (requirements.length === 0) throw new Error("A scored task must require at least one finding");
  const produced = new Set(outputs.flatMap(output => output.findings));
  const satisfied = requirements.filter(finding => produced.has(finding));
  const unnecessaryExecutions = outputs.filter(output => !output.findings.some(finding => requirements.includes(finding))).length;
  return { coverage: satisfied.length / requirements.length, satisfied,
    missing: requirements.filter(finding => !produced.has(finding)), unnecessaryExecutions };
}

import { describe, expect, test, vi } from "vitest";
import { agencies } from "../../../ts/src/domains/supply-chain/agencies";
import * as reinstatement from "../../../ts/src/memory/reinstatement";
import * as execution from "../../../ts/src/society/execution";
import { createWorkspace, directRoute, selectOrganization } from "./baselines";
import { findingsFor, runtimes } from "./capabilities";
import { formationCases, heldOutCases } from "./cases";
import { evaluateCase, runExperiment } from "./run";
import * as scorer from "./scorer";
import { formMemories } from "./training";
import { conditions, type TaskCase } from "./types";

describe("task scorer", () => {
  test("scores required findings downstream of execution, not agency identities", () => {
    expect(scorer.scoreTask(["supplier-risk", "inventory-impact", "production-impact"], [
      { findings: ["supplier-risk", "production-impact"] },
      { findings: ["compliance-verified"] },
    ])).toEqual({ coverage: 2 / 3, satisfied: ["supplier-risk", "production-impact"],
      missing: ["inventory-impact"], unnecessaryExecutions: 1 });
  });

  test("deduplicates findings and does not credit irrelevant outputs", () => {
    expect(scorer.scoreTask(["supplier-risk", "supplier-risk", "route-risk"], [
      { findings: ["supplier-risk", "supplier-risk"] }, { findings: [] },
    ])).toEqual({ coverage: 0.5, satisfied: ["supplier-risk"], missing: ["route-risk"], unnecessaryExecutions: 1 });
    expect(scorer.scoreTask(["supplier-risk"], []).coverage).toBe(0);
    expect(() => scorer.scoreTask([], [])).toThrow("at least one finding");
  });

  test("different capabilities can satisfy the same task and outputs depend on facts", () => {
    const facts = { ...formationCases[0].observation.facts, qualityAlert: true };
    const required = ["supplier-risk", "quality-hold"] as const;
    for (const id of ["SUPPLIER_ASSESSMENT", "RISK_ASSESSMENT"] as const) {
      expect(scorer.scoreTask(required, [{ findings: findingsFor(id, facts) }]).coverage).toBe(1);
      expect(findingsFor(id, { ...facts, supplierUnreliable: false, qualityAlert: false })).not.toContain("supplier-risk");
    }
  });
});

describe("pre-scoring experiment invariants", () => {
  test("formation and held-out identities/literal referents are disjoint", () => {
    const formationIds = new Set(formationCases.map(task => task.id));
    const referents = new Set(formationCases.flatMap(task => task.observation.bindings.map(binding => binding.value)));
    expect(formationCases).toHaveLength(8);
    expect(heldOutCases).toHaveLength(32);
    expect(new Set(heldOutCases.map(task => task.id)).size).toBe(32);
    for (const task of heldOutCases) {
      expect(formationIds.has(task.id)).toBe(false);
      expect(task.requiredFindings.length).toBeGreaterThan(0);
      for (const binding of task.observation.bindings) expect(referents.has(binding.value)).toBe(false);
    }
    for (const kind of ["related", "partial", "unrelated", "misleading"]) {
      expect(heldOutCases.filter(task => task.class === kind)).toHaveLength(8);
    }
  });

  test("unrelated concept sets share no formation concepts; cases vary beyond literal IDs", () => {
    const known = new Set(formationCases.flatMap(task => task.observation.concepts.map(concept => concept.id)));
    for (const task of heldOutCases.filter(task => task.class === "unrelated")) {
      for (const concept of task.observation.concepts) expect(known.has(concept.id)).toBe(false);
    }
    expect(new Set(heldOutCases.map(task => JSON.stringify({ facts: task.observation.facts,
      concepts: task.observation.concepts, requirements: task.requiredFindings }))).size).toBe(32);
  });

  test("the direct baseline uses positive concept membership, not threshold strength", () => {
    const observation = { ...formationCases[0].observation,
      concepts: [{ id: "SHIPMENT_DELAY" as const, strength: 0.01 }] };
    expect(directRoute(observation)).toEqual(["INVENTORY_ASSESSMENT", "LOGISTICS_ASSESSMENT"]);
  });

  test.each(conditions)("%s routing is deterministic and receives no scoring labels", async condition => {
    const { bank } = await formMemories(formationCases);
    const development = { ...formationCases[0] };
    Object.defineProperty(development, "requiredFindings", { get: () => { throw new Error("Label leakage"); } });
    const observation = development.observation;
    expect(Object.keys(observation).sort()).toEqual(["bindings", "concepts", "facts"]);
    const first = selectOrganization(condition, observation, bank);
    const second = selectOrganization(condition, observation, bank);
    expect(first).toStrictEqual(second);
    expect(first.workspace.facts).not.toHaveProperty("requiredFindings");
    expect(first.workspace.facts).not.toHaveProperty("class");
  });

  test("all four conditions use identical configuration, handlers, scorer, and budget", async () => {
    const { bank } = await formMemories(formationCases);
    const executeSpy = vi.spyOn(execution, "executeDispatch");
    const scoreSpy = vi.spyOn(scorer, "scoreTask");
    const reinstateSpy = vi.spyOn(reinstatement, "reinstatementEffects");
    try {
      for (const condition of conditions) {
        const before = executeSpy.mock.calls.length;
        const row = await evaluateCase(formationCases[0], condition, bank);
        expect(row.costs.executionCount).toBeGreaterThan(0);
        expect(row.costs.executionCount).toBeLessThanOrEqual(4);
        const calls = executeSpy.mock.calls.slice(before);
        expect(calls).toHaveLength(row.costs.executionCount);
        for (const [, workspace, config, handlers] of calls) {
          expect(config).toBe(agencies);
          expect(handlers).toBe(runtimes);
          expect(workspace.facts).toEqual(formationCases[0].observation.facts);
        }
      }
      expect(scoreSpy).toHaveBeenCalledTimes(4);
      expect(reinstateSpy).toHaveBeenCalledTimes(1);
    } finally {
      executeSpy.mockRestore(); scoreSpy.mockRestore(); reinstateSpy.mockRestore();
    }
  });

  test("development runs reproduce measurements and summaries exactly without held-out scoring", async () => {
    const development: readonly TaskCase[] = formationCases.map(task => ({ ...task, id: `dev-${task.id}`,
      observation: { ...task.observation, bindings: task.observation.bindings.map(binding => ({ ...binding, value: `dev-${binding.value}` })) } }));
    const snapshot = structuredClone(development);
    const first = await runExperiment(development, formationCases);
    const second = await runExperiment(development, formationCases);
    expect(first).toStrictEqual(second);
    expect(first.measurements).toHaveLength(32);
    expect(development).toStrictEqual(snapshot);
    expect(createWorkspace(development[0].observation).agencyActivations).toEqual([]);
  });
});

import { agencies } from "../../../ts/src/domains/supply-chain/agencies";
import { consolidateKLine } from "../../../ts/src/domains/supply-chain/memory";
import type { KLine } from "../../../ts/src/memory/types";
import { activation } from "../../../ts/src/primitives/activation";
import { runCycle } from "../../../ts/src/society/cycle";
import { createWorkspace } from "./baselines";
import { executeAssessments } from "./capabilities";
import { scoreTask } from "./scorer";
import type { MemoryBank, TaskCase } from "./types";

export async function formMemories(cases: readonly TaskCase[]) {
  const klines: KLine[] = [];
  const episodes: MemoryBank["episodes"][number][] = [];
  const measurements = [];
  for (const task of cases) {
    const cycle = runCycle(createWorkspace(task.observation), agencies);
    const work = await executeAssessments(cycle.workspace, cycle.dispatches);
    const score = scoreTask(task.requiredFindings, work.executions.map(result => result.value));
    const kline = consolidateKLine(`kline_${task.id}`, cycle, activation(score.coverage));
    klines.push(kline);
    episodes.push({ id: kline.id, signature: kline.signature, observation: task.observation,
      advice: { agencyIds: [...cycle.recruitedAgencyIds] } });
    measurements.push({ caseId: task.id, dispatches: cycle.dispatches.length, executions: work.executions.length,
      coverage: score.coverage, storedActivationEntries: kline.agencyActivations.length });
  }
  return { bank: { klines, episodes }, measurements };
}

