import type { Activation } from "../primitives/activation";
import type { AgencyActivation, AgencyId, ConceptId, OperationId, RoleId } from "../primitives/types";
import type { CycleResult } from "../society/cycle";
import type { WorkspaceState } from "../workspace/workspace";
import {
  type Similarity,
  similarity,
} from "./similarity";
import type { KLine, KLineId, SituationSignature } from "./types";

/** Canonical membership and ordering supplied by the reference-domain binding. */
export type KLineIdentityOrder = {
  readonly agencyIds: readonly AgencyId[];
  readonly conceptIds: readonly ConceptId[];
  readonly roleIds: readonly RoleId[];
  readonly operationIds: readonly OperationId[];
};

export type KLineMatch = {
  readonly kline: KLine;
  readonly similarity: Similarity;
};

/**
 * A v0.1 situation signature is the canonical set of
 * non-zero concepts active in the workspace.
 *
 * Activation magnitude is intentionally excluded.
 */
export function deriveSituationSignature(
  workspace: WorkspaceState,
  conceptIds: readonly ConceptId[],
): SituationSignature {
  const activeConceptIds = new Set(
    workspace.polynemes
      .filter(polyneme => polyneme.strength > 0)
      .map(polyneme => polyneme.conceptId),
  );

  return {
    featureIds: conceptIds.filter(
      conceptId => activeConceptIds.has(conceptId),
    ),
  };
}

/**
 * Consolidate one completed cycle into memory for the
 * cognitive organization that formed.
 *
 * Literal pronome referents are deliberately excluded.
 */
export function consolidateKLine(
  id: KLineId,
  cycle: CycleResult,
  utility: Activation,
  { agencyIds, conceptIds, roleIds, operationIds }: KLineIdentityOrder,
): KLine {
  const recruitedAgencyIds = new Set(
    cycle.recruitedAgencyIds,
  );

  const activationsByAgency = new Map(
    cycle.workspace.agencyActivations.map(
      agencyActivation => [
        agencyActivation.agencyId,
        agencyActivation,
      ] as const,
    ),
  );

  const agencyActivations: AgencyActivation[] =
    agencyIds.flatMap(agencyId => {
      if (!recruitedAgencyIds.has(agencyId)) {
        return [];
      }

      const agencyActivation =
        activationsByAgency.get(agencyId);

      if (!agencyActivation) {
        throw new Error(
          `Missing activation for recruited agency: ${agencyId}`,
        );
      }

      return [{
        agencyId,
        activation: agencyActivation.activation,
      }];
    });

  const boundRoleIds = new Set(
    cycle.workspace.pronomes.map(
      pronome => pronome.roleId,
    ),
  );

  const consolidatedRoleIds = roleIds.filter(
    roleId => boundRoleIds.has(roleId),
  );

  const dispatchedOperationIds = new Set(
    cycle.dispatches.map(
      dispatch => dispatch.operationId,
    ),
  );

  const consolidatedOperationIds =
    operationIds.filter(
      operationId =>
        dispatchedOperationIds.has(operationId),
    );

  return {
    id,
    signature:
      deriveSituationSignature(cycle.workspace, conceptIds),

    agencyActivations,
    roleIds: consolidatedRoleIds,
    operationIds: consolidatedOperationIds,

    utility,
  };
}

/**
 * Jaccard similarity over situation feature sets.
 *
 * Empty signatures deliberately produce zero similarity:
 * absence of features is not treated as evidence of
 * structural similarity.
 */
export function situationSimilarity(
  left: SituationSignature,
  right: SituationSignature,
): Similarity {
  const leftFeatures = new Set(left.featureIds);
  const rightFeatures = new Set(right.featureIds);

  if (leftFeatures.size === 0 || rightFeatures.size === 0) {
    return similarity(0);
  }

  let intersectionSize = 0;

  for (const featureId of leftFeatures) {
    if (rightFeatures.has(featureId)) {
      intersectionSize += 1;
    }
  }

  const unionSize = new Set([
    ...leftFeatures,
    ...rightFeatures,
  ]).size;

  return similarity(intersectionSize / unionSize);
}

/**
 * Recall K-lines whose situation signatures structurally
 * overlap with the current situation.
 *
 * v0.1 retrieval uses concept structure only.
 *
 * Returned memories are ranked by:
 *   1. similarity descending
 *   2. K-line ID ascending
 */
export function recallKLines(
  signature: SituationSignature,
  kLines: readonly KLine[],
  minimumSimilarity: Similarity,
): readonly KLineMatch[] {
  return kLines
    .flatMap<KLineMatch>(kline => {
      const score = situationSimilarity(signature, kline.signature);

      if (score === 0 || score < minimumSimilarity) {
        return [];
      }

      return [{
        kline,
        similarity: score,
      }];
    })
    .sort((left, right) => {
      if (left.similarity !== right.similarity) {
        return right.similarity - left.similarity;
      }

      if (left.kline.id < right.kline.id) {
        return -1;
      }

      if (left.kline.id > right.kline.id) {
        return 1;
      }

      return 0;
    });
}

import { describe, expect, test } from "vitest";
import { type Activation, activation } from "../primitives/activation";
import type { KLineMatch } from "./kline";
import { reinstatementEffects } from "./reinstatement";
import { similarity } from "./similarity";
import type { KLine } from "./types";

function memory(overrides: Partial<KLine> = {}): KLine {
  return {
    id: "kline_prior",
    signature: { featureIds: ["SHIPMENT_DELAY"] },
    agencyActivations: [
      { agencyId: "SUPPLIER_ASSESSMENT", activation: activation(0.8) },
      { agencyId: "INVENTORY_ASSESSMENT", activation: activation(0.3) },
    ],
    roleIds: ["SUPPLIER", "SHIPMENT"],
    operationIds: ["VERIFY"],
    utility: activation(0.2),
    ...overrides,
  };
}

describe("reinstatementEffects", () => {
  test.each([
    { score: 1, supplier: 0.8, inventory: 0.3 },
    { score: 0.5, supplier: 0.4, inventory: 0.15 },
  ])("scales stored activation by similarity $score in consolidated order", ({ score, supplier, inventory }) => {
    expect(reinstatementEffects({ kline: memory(), similarity: similarity(score) })).toEqual([
      { action: "activate_agency", agencyId: "SUPPLIER_ASSESSMENT", amount: expect.closeTo(supplier, 12) },
      { action: "activate_agency", agencyId: "INVENTORY_ASSESSMENT", amount: expect.closeTo(inventory, 12) },
    ]);
  });

  test("zero similarity produces no Effects", () => {
    expect(reinstatementEffects({ kline: memory(), similarity: similarity(0) })).toEqual([]);
  });

  test("omits zero stored activations without changing the remaining order", () => {
    const kline = memory({ agencyActivations: [
      { agencyId: "SUPPLIER_ASSESSMENT", activation: activation(0) },
      { agencyId: "INVENTORY_ASSESSMENT", activation: activation(0.3) },
    ] });

    expect(reinstatementEffects({ kline, similarity: similarity(1) })).toEqual([
      { action: "activate_agency", agencyId: "INVENTORY_ASSESSMENT", amount: activation(0.3) },
    ]);
  });

  test("full stored activation and similarity produce bounded activation 1", () => {
    const kline = memory({ agencyActivations: [
      { agencyId: "SUPPLIER_ASSESSMENT", activation: activation(1) },
    ] });

    expect(reinstatementEffects({ kline, similarity: similarity(1) })).toEqual([
      { action: "activate_agency", agencyId: "SUPPLIER_ASSESSMENT", amount: activation(1) },
    ]);
  });

  test("an empty remembered coalition produces no Effects", () => {
    expect(reinstatementEffects({
      kline: memory({ agencyActivations: [] }), similarity: similarity(1),
    })).toEqual([]);
  });

  test.each([0, 1])("utility %s does not modulate reinstatement", utility => {
    const baseline = { kline: memory(), similarity: similarity(0.5) };
    const changed = { ...baseline, kline: memory({ utility: activation(utility) }) };

    expect(reinstatementEffects(changed)).toStrictEqual(reinstatementEffects(baseline));
  });

  test.each([
    { label: "roles", overrides: { roleIds: ["CUSTOMER"] } },
    { label: "operations", overrides: { operationIds: ["ESCALATE", "RESOLVE"] } },
    { label: "signature", overrides: { signature: { featureIds: ["QUALITY_RISK"] } } },
    { label: "identity", overrides: { id: "kline_other" } },
  ] satisfies readonly { label: string; overrides: Partial<KLine> }[])("ignores stored $label when deriving a supplied match", ({ overrides }) => {
    const baseline = { kline: memory(), similarity: similarity(0.5) };
    const changed = { ...baseline, kline: memory(overrides) };

    expect(reinstatementEffects(changed)).toStrictEqual(reinstatementEffects(baseline));
  });

  test("is deterministic and leaves a deeply frozen match and its collections unchanged", () => {
    const original = memory();
    const kline: KLine = Object.freeze({
      ...original,
      signature: Object.freeze({ featureIds: Object.freeze([...original.signature.featureIds]) }),
      agencyActivations: Object.freeze(original.agencyActivations.map(entry => Object.freeze({ ...entry }))),
      roleIds: Object.freeze([...original.roleIds]),
      operationIds: Object.freeze([...original.operationIds]),
    });
    const match: KLineMatch = Object.freeze({ kline, similarity: similarity(0.5) });
    const snapshot = structuredClone(match);

    const first = reinstatementEffects(match);
    const second = reinstatementEffects(match);

    expect(first).toStrictEqual(second);
    expect(match).toStrictEqual(snapshot);
  });

  test("passes computed contributions through the existing Activation invariant", () => {
    const kline = memory({ agencyActivations: [
      // Deliberately bypass the input brand to check the output invariant.
      { agencyId: "SUPPLIER_ASSESSMENT", activation: 2 as Activation },
    ] });

    expect(() => reinstatementEffects({ kline, similarity: similarity(1) }))
      .toThrow("activation must be a number >= 0 and <= 1");
  });
});

import { activation } from "../primitives/activation";
import type { ActivateAgency } from "../workspace/effect";
import type { KLineMatch } from "./kline";

/**
 * Derive one memory's activation prior in stored (consolidated canonical) order.
 * The caller applies Effects and controls their ordering relative to evidence.
 * Recall, recruitment, utility, roles, and operations remain separate.
 */
export function reinstatementEffects(match: KLineMatch): readonly ActivateAgency[] {
  return match.kline.agencyActivations.flatMap<ActivateAgency>(stored => {
    const amount = activation(stored.activation * match.similarity);

    if (amount === 0) return [];

    return [{
      action: "activate_agency",
      agencyId: stored.agencyId,
      amount,
    }];
  });
}

import { describe, expect, test } from "vitest";
import {
  similarity,
} from "./similarity";

describe("similarity", () => {
  test.each([
    0,
    0.25,
    0.5,
    1,
  ])("accepts %s", value => {
    expect(similarity(value)).toBe(value);
  });

  test.each([
    -0.01,
    1.01,
    Number.NaN,
    Number.POSITIVE_INFINITY,
    Number.NEGATIVE_INFINITY,
  ])("rejects invalid similarity %s", value => {
    expect(() => similarity(value))
      .toThrow(
        "similarity must be a finite number >= 0 and <= 1",
      );
  });
});

declare const similaritySymbol: unique symbol;

export type Similarity = number & {
  readonly [similaritySymbol]: true;
};

export function similarity(value: number): Similarity {
  if (Number.isFinite(value) && value >= 0 && value <= 1) {
    return value as Similarity;
  }

  throw new Error('similarity must be a finite number >= 0 and <= 1');
}

import type { Activation } from "../primitives/activation";
import type { AgencyActivation, ConceptId, OperationId, RoleId } from "../primitives/types";

export type SituationFeatureId = ConceptId;
export type KLineId = `kline_${string}`;

export type SituationSignature = {
	featureIds: readonly SituationFeatureId[];
};

export type KLine = {
  id: KLineId;
  signature: SituationSignature;

  agencyActivations: readonly AgencyActivation[];
  roleIds: readonly RoleId[];
