      ...createEmptyWorkspace(),
      polynemes: [
        {
          kind: "polyneme",
          conceptId: "SHIPMENT_DELAY",
          strength: activation(0.5),
        },
      ],
      agencyActivations: [
        {
          agencyId: "SUPPLIER_ASSESSMENT",
          activation: activation(0.2),
