        sensitivities: {
          SHIPMENT_DELAY: activation(1),
        },
        supportedOperations: ["COMPARE", "ESCALATE"],
      },
    ];

    const workspace: WorkspaceState = {
      ...createEmptyWorkspace(),
      polynemes: [
        {
          kind: "polyneme",
