    const result = runCycle(workspace, configuration);

    expect(result.recruitedAgencyIds).toEqual([
      "SUPPLIER_ASSESSMENT",
      "PROCUREMENT_STRATEGY",
    ]);

    expect(result.dispatches).toEqual([
      {
        agencyId: "SUPPLIER_ASSESSMENT",
