      {
        id: "LOGISTICS_ASSESSMENT",
        threshold: activation(0.5),
        sensitivities: {
          SHIPMENT_DELAY: activation(1),
        },
        supportedOperations: ["VERIFY", "ESCALATE"],
      },
      {
        id: "PROCUREMENT_STRATEGY",
        threshold: activation(0.5),
