    expect(effects).toHaveLength(1);
    expect(effects[0]).toMatchObject({ action: 'activate_agency', agencyId: 'SUPPLIER_ASSESSMENT' });
    expect(effects[0].amount).toBeCloseTo(contribution, 12);
