      { agencyId: 'PROCUREMENT_STRATEGY', activation: expect.closeTo(0.87, 12) },
      { agencyId: 'COMPLIANCE_ASSESSMENT', activation: expect.closeTo(0.15, 12) },
      { agencyId: 'RISK_ASSESSMENT', activation: activation(1) },
