import { type Activation, activation } from "../primitives/activation";
import type { AgencyId, ConceptId, OperationId, RoleId } from "../primitives/types";
import { Pronome } from "./pronome";
import type { WorkspaceState } from "./workspace";

const pronomeActions = [
  'bind_pronome',
  'record_fact',
  'emit_polyneme',
  'invoke_isonome',
  'activate_agency',
  'inhibit_agency',
];

export type PronomeAction = (typeof pronomeActions)[number];

type BindPronome<T> = {
  action: 'bind_pronome';
  roleId: RoleId;
  value: T;
}

type RecordFact = {
  action: 'record_fact';
  key: string;
  value: unknown;
};

type EmitPolyneme = {
  action: 'emit_polyneme';
  conceptId: ConceptId;
  strength: Activation;
}

type InvokeIsonome = {
  action: 'invoke_isonome';
  operationId: OperationId;
  strength: Activation;
}

export type ActivateAgency = {
  action: 'activate_agency';
  agencyId: AgencyId;
  amount: Activation;
}

type InhibitAgency = {
  action: 'inhibit_agency';
  agencyId: AgencyId;
  amount: Activation;
}


export type Effect<T = unknown> =
  | BindPronome<T>
  | RecordFact
  | EmitPolyneme
  | InvokeIsonome
  | ActivateAgency
  | InhibitAgency;



/***
 * Utils and helpers
 */

function assertNever(value: never): never {
  throw new Error(`Unhandled effect: ${JSON.stringify(value)}`);
}

function min(a: number, b: number): Activation {
  return activation(Math.min(a, b));
}

function max(a: number, b: number): Activation {
  return activation(Math.max(a, b));
}

/***
 * addiing delta with saturation
 * because we want a maximum of 1
 * regardless of the input values
 * Example: add(.5, .8) = 1.3 => 1
 */
function add(a: Activation, b: Activation): Activation {
  return min(1, a + b)
}

/***
 * subtracting delta with saturation
 * becausee we want a minimum of 0
 * regardless of the input values
 * Example: subtract(.2, .9) = -0.7 => 0
 */
function subtract(a: Activation, b: Activation): Activation {
  return max(0, a - b);
};






/***
 * Core effect handlers
 */
function bindPronome(w: WorkspaceState, e: Extract<Effect, { action: 'bind_pronome' }>): WorkspaceState {
  const exists = w.pronomes.some(p => p.roleId === e.roleId);

  return {
    ...w,
    pronomes: exists
      ? w.pronomes.map((p) => {
          if (p.roleId === e.roleId) {
            return p.bind(e.value)
          }
          return p
        })
      : [...w.pronomes, new Pronome(e.roleId, e.value)],
  }
}


function recordFact(w: WorkspaceState, e: Extract<Effect, { action: 'record_fact' }>): WorkspaceState {
  return {
    ...w,
    facts: { ...w.facts, [e.key]: e.value },
  }
}

function emitPolyneme(w: WorkspaceState, e: Extract<Effect, { action: 'emit_polyneme' }>): WorkspaceState {
  const exists = w.polynemes.some(p => p.conceptId === e.conceptId);

  return {
			...w,
			polynemes: exists
				? w.polynemes.map((p) => {
						if (p.conceptId === e.conceptId) {
							return { ...p, strength: add(p.strength, e.strength) };
						}
						return p;
					})
        : [...w.polynemes, { kind: 'polyneme', conceptId: e.conceptId, strength: e.strength }],
		};
}

function invokeIsonome(w: WorkspaceState, e: Extract<Effect, { action: 'invoke_isonome' }>): WorkspaceState {
  const exists = w.isonomes.some(p => p.operationId === e.operationId);

  return {
			...w,
			isonomes: exists
				? w.isonomes.map((i) => {
						if (i.operationId === e.operationId) {
							return { ...i, strength: add(i.strength, e.strength) };
						}
						return i;
					})
				: [...w.isonomes, { kind: 'isonome', operationId: e.operationId, strength: e.strength }],
		};
}

function activateAgency(w: WorkspaceState, e: Extract<Effect, { action: 'activate_agency' }>): WorkspaceState {
  const exists = w.agencyActivations.some(aa => aa.agencyId === e.agencyId);

  return {
		...w,
    agencyActivations: exists
      ? w.agencyActivations.map((aa) => {
          if (aa.agencyId === e.agencyId) {
            return { ...aa, activation: add(aa.activation, e.amount) };
          }
          return aa;
        })
      : [...w.agencyActivations, { agencyId: e.agencyId, activation: e.amount }],
	};
}

function inhibitAgency(w: WorkspaceState, e: Extract<Effect, { action: 'inhibit_agency' }>): WorkspaceState {
  const exists = w.agencyActivations.some(aa => aa.agencyId === e.agencyId);

  return {
    ...w,
    agencyActivations: exists
      ? w.agencyActivations.map((aa) => {
          if (aa.agencyId === e.agencyId) {
              return { ...aa, activation: subtract(aa.activation, e.amount) };
            }
            return aa;
        })
      : w.agencyActivations,
  }
}

export function applyEffect(w: WorkspaceState, e: Effect): WorkspaceState {
  switch (e.action) {
    case 'bind_pronome':
      return bindPronome(w, e);
    case 'record_fact':
      return recordFact(w, e);
    case 'emit_polyneme':
      return emitPolyneme(w, e)
    case 'invoke_isonome':
      return invokeIsonome(w, e);
    case 'activate_agency':
      return activateAgency(w, e);
    case 'inhibit_agency':
      return inhibitAgency(w, e)
    default:
       return assertNever(e);
  }
};

import { describe, expect, test } from 'vitest';

import { Pronome } from './pronome';

describe('Pronome', () => {
  test('pronome should bind to new value keeping the existing roleId', () => {
    const ROLE_ID = 'CARRIER';
    const FIRST_CARRIER = 'carrier_delta';
    const SECOND_CARRIER = 'carrier_echo';

    const firstCarrierPronome = new Pronome(ROLE_ID, FIRST_CARRIER);

    expect(firstCarrierPronome.roleId).toBe(ROLE_ID);
    expect(firstCarrierPronome.value).toBe(FIRST_CARRIER);

    const secondCarrierPronome = firstCarrierPronome.bind(SECOND_CARRIER);

    expect(secondCarrierPronome.roleId).toBe(ROLE_ID);
    expect(secondCarrierPronome.value).toBe(SECOND_CARRIER);
    expect(firstCarrierPronome.roleId).toBe(ROLE_ID);
    expect(firstCarrierPronome.value).toBe(FIRST_CARRIER);
  });
});

import type { RoleId } from "../primitives/types";


export class Pronome<T>  {
  private readonly _roleId: RoleId;
  private readonly _value: T;

  constructor(roleId: RoleId, value: T) {
    this._roleId = roleId;
    this._value = value;
  }

  get roleId() {
    return this._roleId;
  }

  get value() {
    return this._value;
  }

  bind(value: T) {
    return new Pronome<T>(this.roleId, value);
  }
}

import { describe, expect, test } from 'vitest';
import { activation } from '../primitives/activation';
import { applyEffect, type Effect } from './effect';
import { createEmptyWorkspace } from './workspace';

describe('createEmptyWorkspace', () => {
  test('creates the canonical empty state', () => {
    expect(createEmptyWorkspace()).toStrictEqual({
      facts: {},
      pronomes: [],
      polynemes: [],
      isonomes: [],
      agencyActivations: [],
    });
  });

  test('creates independent state containers for each workspace', () => {
    const first = createEmptyWorkspace();
    const second = createEmptyWorkspace();

    expect(first).not.toBe(second);
    expect(first.facts).not.toBe(second.facts);
    expect(first.pronomes).not.toBe(second.pronomes);
    expect(first.polynemes).not.toBe(second.polynemes);
    expect(first.isonomes).not.toBe(second.isonomes);
    expect(first.agencyActivations).not.toBe(second.agencyActivations);
  });
});

describe('workspace episode integration', () => {
  test('composes bindings, facts, signals, and agency activations into a realistic episode', () => {
    const initial = createEmptyWorkspace();
    const episode: readonly Effect[] = [
      { action: 'bind_pronome', roleId: 'SUPPLIER', value: 'supplier_1' },
      { action: 'bind_pronome', roleId: 'COMPONENT', value: 'component_1' },
      { action: 'bind_pronome', roleId: 'SHIPMENT', value: 'shipment_1' },
      { action: 'record_fact', key: 'inventory.daysRemaining', value: 1 },
      { action: 'record_fact', key: 'shipment.status', value: 'delayed' },
      { action: 'emit_polyneme', conceptId: 'SHIPMENT_DELAY', strength: activation(0.8) },
      { action: 'emit_polyneme', conceptId: 'SUPPLIER_RELIABILITY_RISK', strength: activation(0.6) },
      { action: 'activate_agency', agencyId: 'SUPPLIER_ASSESSMENT', amount: activation(0.7) },
      { action: 'activate_agency', agencyId: 'LOGISTICS_ASSESSMENT', amount: activation(0.5) },
      { action: 'invoke_isonome', operationId: 'VERIFY', strength: activation(0.4) },
    ];

    const workspace = episode.reduce((state, effect) => applyEffect(state, effect), initial);

    expect(workspace.facts).toEqual({ 'inventory.daysRemaining': 1, 'shipment.status': 'delayed' });
    expect(workspace.pronomes.map(p => ({ roleId: p.roleId, value: p.value }))).toEqual([
      { roleId: 'SUPPLIER', value: 'supplier_1' },
      { roleId: 'COMPONENT', value: 'component_1' },
      { roleId: 'SHIPMENT', value: 'shipment_1' },
    ]);
    expect(workspace.polynemes).toEqual([
      { kind: 'polyneme', conceptId: 'SHIPMENT_DELAY', strength: activation(0.8) },
      { kind: 'polyneme', conceptId: 'SUPPLIER_RELIABILITY_RISK', strength: activation(0.6) },
    ]);
    expect(workspace.agencyActivations).toEqual([
      { agencyId: 'SUPPLIER_ASSESSMENT', activation: activation(0.7) },
      { agencyId: 'LOGISTICS_ASSESSMENT', activation: activation(0.5) },
    ]);
    expect(workspace.isonomes).toEqual([
      { kind: 'isonome', operationId: 'VERIFY', strength: activation(0.4) },
    ]);
    expect(initial).toStrictEqual(createEmptyWorkspace());
  });
});

import type { AgencyActivation, Isonome, Polyneme } from "../primitives/types";
import type { Pronome } from "./pronome";

export type WorkspaceState = {
	readonly facts: Readonly<Record<string, unknown>>;
  readonly pronomes: readonly Pronome<unknown>[];
  readonly polynemes: readonly Polyneme[];
  readonly isonomes: readonly Isonome[];
  readonly agencyActivations: readonly AgencyActivation[];
};

export function createEmptyWorkspace(): WorkspaceState {
  return {
  	facts: {},
  	pronomes: [],
  	polynemes: [],
  	isonomes: [],
  	agencyActivations: [],
  }
};

